fn remove_duplicates(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }
    let mut unique_count = 1;
    for i in 1..nums.len() {
        if nums[i] != nums[i - 1] {
            unique_count += 1;
        }
    }
    unique_count
}

